SELECT store_id, CASE WHEN quantity >= 204 THEN 'PREMIUM' ELSE 'STANDARD' END AS quantity_tier, ROUND(AVG(quantity), 2) AS avg_quantity, STDDEV_SAMP(quantity) AS quantity_stddev, BIT_AND(quantity) AS quantity_bit_and, STDDEV_SAMP(quantity) AS quantity_stddev_2, BIT_OR(quantity) AS quantity_bit_or FROM inventory GROUP BY store_id, CASE WHEN quantity >= 204 THEN 'PREMIUM' ELSE 'STANDARD' END;
